#!/bin/bash
# Fase 8Q2: documentacion real asociada a los pedidos -- albaran de entrega
# y carta de porte (control de mercancia por carretera), generados en PDF,
# con QR de verificacion publica, en el propio TMS. Tercer punto que habia
# quedado aplazado del backlog de "Ficha unica del pedido".
#
# Ejecutar desde la carpeta raiz del proyecto (la que tiene frontend,
# backend y apps dentro), con Git Bash:
#   bash apply_fase8q2_documentacion_legal.sh
#
# Aplica 18 ficheros (11 backend, 5 Backoffice, 2 App Conductor). Incluye
# un cambio de esquema aditivo (datos de la empresa para la cabecera de los
# documentos) -- ver el aviso IMPORTANTE al final de este script.
set -e
if [ ! -d "frontend" ] || [ ! -d "backend" ] || [ ! -d "apps" ]; then
  echo "ERROR: ejecuta este script desde la carpeta raiz del proyecto (debe contener frontend, backend y apps)."
  exit 1
fi

mkdir -p "backend/prisma"
echo  | base64 -d > "backend/prisma/schema.prisma"
echo "  ok: backend/prisma/schema.prisma"
mkdir -p "backend"
echo  | base64 -d > "backend/package.json"
echo "  ok: backend/package.json"
mkdir -p "backend"
echo  | base64 -d > "backend/package-lock.json"
echo "  ok: backend/package-lock.json"
mkdir -p "backend/src"
echo  | base64 -d > "backend/src/app.ts"
echo "  ok: backend/src/app.ts"
mkdir -p "backend/src/modules/orders"
echo  | base64 -d > "backend/src/modules/orders/orders.routes.ts"
echo "  ok: backend/src/modules/orders/orders.routes.ts"
mkdir -p "backend/src/modules/routes"
echo  | base64 -d > "backend/src/modules/routes/routes.routes.ts"
echo "  ok: backend/src/modules/routes/routes.routes.ts"
mkdir -p "backend/src/modules/portal"
echo  | base64 -d > "backend/src/modules/portal/driver-app.routes.ts"
echo "  ok: backend/src/modules/portal/driver-app.routes.ts"
mkdir -p "backend/src/modules/company"
echo  | base64 -d > "backend/src/modules/company/company-settings.routes.ts"
echo "  ok: backend/src/modules/company/company-settings.routes.ts"
mkdir -p "backend/src/modules/documents"
echo  | base64 -d > "backend/src/modules/documents/document-pdf.service.ts"
echo "  ok: backend/src/modules/documents/document-pdf.service.ts"
mkdir -p "backend/src/modules/documents"
echo  | base64 -d > "backend/src/modules/documents/public-documents.routes.ts"
echo "  ok: backend/src/modules/documents/public-documents.routes.ts"
mkdir -p "backend/src/middleware"
echo  | base64 -d > "backend/src/middleware/documents-rate-limit.ts"
echo "  ok: backend/src/middleware/documents-rate-limit.ts"
mkdir -p "frontend/src/lib"
echo  | base64 -d > "frontend/src/lib/document-pdf.ts"
echo "  ok: frontend/src/lib/document-pdf.ts"
mkdir -p "frontend/src/pages/orders"
echo  | base64 -d > "frontend/src/pages/orders/OrderDetailModal.tsx"
echo "  ok: frontend/src/pages/orders/OrderDetailModal.tsx"
mkdir -p "frontend/src/pages/planner"
echo  | base64 -d > "frontend/src/pages/planner/RouteAssignmentModal.tsx"
echo "  ok: frontend/src/pages/planner/RouteAssignmentModal.tsx"
mkdir -p "frontend/src/pages/masters"
echo  | base64 -d > "frontend/src/pages/masters/ProductsPage.tsx"
echo "  ok: frontend/src/pages/masters/ProductsPage.tsx"
mkdir -p "frontend/src/pages"
echo  | base64 -d > "frontend/src/pages/CompanySettingsPage.tsx"
echo "  ok: frontend/src/pages/CompanySettingsPage.tsx"
mkdir -p "apps/driver-app/src/lib"
echo  | base64 -d > "apps/driver-app/src/lib/document-pdf.ts"
echo "  ok: apps/driver-app/src/lib/document-pdf.ts"
mkdir -p "apps/driver-app/src/pages"
echo  | base64 -d > "apps/driver-app/src/pages/StopDetailPage.tsx"
echo "  ok: apps/driver-app/src/pages/StopDetailPage.tsx"

echo ""
echo "Listo. 18 ficheros actualizados."
echo ""
echo "=========================================================================="
echo "IMPORTANTE -- este cambio SI toca la base de datos (nuevos campos opcionales"
echo "en Company: direccion/telefono/email/etc. para la cabecera de los documentos)."
echo "Antes de dar por bueno el despliegue:"
echo "  1) Sube este commit (git add / commit / push, o hazlo desde GitHub Desktop"
echo "     sin marcar este .sh)."
echo "  2) En Google Cloud Shell: entra en la carpeta del proyecto y ejecuta"
echo "     git pull origin main -- MUY IMPORTANTE hacerlo justo antes de nada mas:"
echo "     si la copia esta desactualizada, prisma db push no hace nada de verdad"
echo "     aunque diga que ha ido bien (ya nos paso una vez)."
echo "  3) cd backend"
echo "  4) Comprueba que el fichero .env sigue ahi con la conexion real de Neon"
echo "     (cat .env) -- si no esta, vuelve a crearlo con el DATABASE_URL que ves"
echo "     en Cloud Run -> tms-backend -> Editar e implementar nueva revision ->"
echo "     Contenedor -> Variables y secretos."
echo "  5) npx prisma db push"
echo "  6) Cuando termine el despliegue de GitHub Actions, ve a Backoffice ->"
echo "     Configuracion y rellena los datos de la empresa (direccion, telefono,"
echo "     email, Registro Mercantil) para que salgan en los documentos."
echo "=========================================================================="
